package langfun;

public class Constructorsam {
int n;
double d;

	Constructorsam(){
		this.n = n;
		this.d = d;
	}


	public static void main(String[] args) {
		// TODO Auto-generated method stub
		Constructorsam a = new Constructorsam();
		System.out.println(a.n);
		System.out.println(a.d);
		

	}

}
